def smallest_change(arr):
    def is_palindrome(sub_arr):
        return sub_arr == sub_arr[::-1]

    def min_changes(sub_arr):
        changes = 0
        left, right = 0, len(sub_arr) - 1
        while left < right:
            if sub_arr[left] != sub_arr[right]:
                changes += 1
            left += 1
            right -= 1
        return changes

    if len(arr) <= 1:
        return 0

    middle = len(arr) // 2
    left_sub_arr = arr[:middle]
    right_sub_arr = arr[middle + len(arr) % 2:]

    if is_palindrome(arr):
        return 0
    elif is_palindrome(left_sub_arr) or is_palindrome(right_sub_arr):
        return 1
    else:
        return min(min_changes(left_sub_arr), min_changes(right_sub_arr))

